// Locks the image loading looks in Hero's skeleton family (ported from the
// reference's app_shimmer_logo_test.dart, re-skinned; docs/image_pipeline.md):
//   * the still box: AppColors.divider, the image's shape, no glyph;
//   * the bag mask (assets/images/hero_shimmer_mask.png, generated by
//     `flutter test tool/gen_hero_shimmer_mask.dart`): tiny, 256 px,
//     white-on-transparent, shipped in the bundle, decoded ONCE;
//   * the painter: base AppColors.divider, the band to AppColors
//     .smallBackground entering from the START edge (RTL mirrored), the bag
//     tinted with the highlight at 90 %, HeroImagePlaceholder's size rule,
//     nothing painted outside the tile, a still frame = base + bag;
//   * caches: one painter per look, one Paint per tint;
//   * ONE ticker, attached only by live shimmers — never under reduced
//     motion, with TickerMode off, or frozen.

import 'dart:io';
import 'dart:typed_data';
import 'dart:ui' as ui;

import 'package:flutter/material.dart';
import 'package:flutter/rendering.dart';
import 'package:flutter_svg/flutter_svg.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:hero_mart/src/config/theme/app_colors.dart';
import 'package:hero_mart/src/core/design/hero_assets.dart';
import 'package:hero_mart/src/core/motion/motion.dart';
import 'package:hero_mart/src/core/widgets/hero_image_placeholder.dart';
import 'package:hero_mart/src/core/widgets/hero_image_shape.dart';
import 'package:hero_mart/src/core/widgets/hero_image_shimmer.dart';
import 'package:hero_mart/src/core/widgets/hero_image_shimmer_painter.dart';
import 'package:hero_mart/src/core/widgets/hero_image_still_box.dart';
import 'package:hero_mart/src/core/widgets/hero_shimmer_clock.dart';
import 'package:hero_mart/src/core/widgets/hero_shimmer_mask.dart';
import 'package:hero_mart/src/core/widgets/hero_shimmer_paints.dart';

const Key _boundary = ValueKey<String>('shimmer-boundary');

Widget _host(
  List<Widget> tiles, {
  TextDirection direction = TextDirection.ltr,
  bool reduced = false,
  bool tickers = true,
}) => MediaQuery(
  data: MediaQueryData(disableAnimations: reduced),
  child: TickerMode(
    enabled: tickers,
    child: Directionality(
      textDirection: direction,
      child: Center(
        child: RepaintBoundary(
          key: _boundary,
          child: Row(mainAxisSize: MainAxisSize.min, children: tiles),
        ),
      ),
    ),
  ),
);

HeroImageShimmer _tile({
  double size = 200,
  bool animate = false,
  bool circular = false,
  double radius = 0,
}) => HeroImageShimmer(
  shape: HeroImageShape(
    width: size,
    height: size,
    radius: radius,
    circular: circular,
  ),
  animate: animate,
);

HeroImageShimmerPainter _painterOf(WidgetTester t) =>
    t
            .widget<CustomPaint>(
              find.descendant(
                of: find.byType(HeroImageShimmer),
                matching: find.byType(CustomPaint),
              ),
            )
            .painter!
        as HeroImageShimmerPainter;

Future<ByteData> _rgba(ui.Image image) async =>
    (await image.toByteData(format: ui.ImageByteFormat.rawStraightRgba))!;

/// The boundary's pixels (logical px at ratio 1).
Future<ByteData> _shot(WidgetTester t) async {
  final RenderRepaintBoundary boundary = t.renderObject<RenderRepaintBoundary>(
    find.byKey(_boundary),
  );
  return (await t.runAsync(() async {
    final ui.Image shot = await boundary.toImage();
    final ByteData data = await _rgba(shot);
    shot.dispose();
    return data;
  }))!;
}

/// Waits (real time) for the mask decode the mounted tiles started, then
/// paints the frame its generation tick schedules.
Future<ui.Image> _awaitMask(WidgetTester t) async {
  final ui.Image? mask = await _loadMask(t);
  await t.pump();
  return mask!;
}

/// [HeroShimmerMask.ensureLoaded] in real time.
Future<ui.Image?> _loadMask(WidgetTester t) =>
    t.runAsync<ui.Image?>(HeroShimmerMask.ensureLoaded);

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();
  setUp(HeroShimmerMask.debugReset);

  group('still box', () {
    testWidgets('the skeleton grey, the image shape, no glyph', (t) async {
      await t.pumpWidget(
        _host(const <Widget>[
          HeroImageStillBox(shape: HeroImageShape(width: 56, height: 56)),
          HeroImageStillBox(
            shape: HeroImageShape(width: 56, height: 56, radius: 12),
          ),
          HeroImageStillBox(
            shape: HeroImageShape(width: 64, height: 64, circular: true),
          ),
        ]),
      );
      expect(HeroImageStillBox.color, AppColors.divider);
      expect(
        t.widget<ColoredBox>(find.byType(ColoredBox)).color,
        AppColors.divider,
      );
      final List<BoxDecoration> decorations = t
          .widgetList<DecoratedBox>(find.byType(DecoratedBox))
          .map((DecoratedBox d) => d.decoration as BoxDecoration)
          .toList();
      expect(decorations, hasLength(2));
      expect(decorations[0].borderRadius, BorderRadius.circular(12));
      expect(decorations[0].color, AppColors.divider);
      expect(decorations[1].shape, BoxShape.circle);
      expect(find.byType(SvgPicture), findsNothing);
      expect(find.byType(CustomPaint), findsNothing, reason: 'painted once');
      expect(t.binding.hasScheduledFrame, isFalse);
    });
  });

  group('mask asset', () {
    test('≤ 4 KB, 256×256, white silhouette on transparent', () async {
      final Uint8List bytes = File(HeroAssets.imageShimmerMask)
          .readAsBytesSync();
      expect(bytes.length, lessThanOrEqualTo(4 * 1024));

      final ui.Codec codec = await ui.instantiateImageCodec(bytes);
      final ui.Image image = (await codec.getNextFrame()).image;
      codec.dispose();
      expect(image.width, HeroShimmerMask.decodeSize);
      expect(image.height, HeroShimmerMask.decodeSize);

      final ByteData px = await _rgba(image);
      const int side = 256;
      int alpha(int x, int y) => px.getUint8((y * side + x) * 4 + 3);
      for (final (int x, int y) in const <(int, int)>[
        (0, 0),
        (255, 0),
        (0, 255),
        (255, 255),
        (128, 128), // the bag's inside: an outline, not a fill
      ]) {
        expect(alpha(x, y), 0, reason: '($x,$y) must be transparent');
      }
      int opaque = 0, visible = 0;
      for (int i = 0; i < px.lengthInBytes; i += 4) {
        final int a = px.getUint8(i + 3);
        if (a == 0) continue;
        visible++;
        if (a == 255) opaque++;
        expect(
          <int>[px.getUint8(i), px.getUint8(i + 1), px.getUint8(i + 2)],
          <int>[255, 255, 255],
          reason: 'every visible pixel is white (alpha carries the shape)',
        );
      }
      // The bag's outline: a solid stroke, mostly fully opaque.
      expect(opaque, greaterThan(side * side ~/ 40));
      expect(opaque, greaterThan(visible ~/ 2));
      image.dispose();
    });

    testWidgets('ships in the bundle and decodes through the cache', (t) async {
      final ui.Image? mask = await _loadMask(t);
      expect(mask, isNotNull);
      expect((mask!.width, mask.height), (256, 256));
      expect(HeroShimmerMask.mask?.src, const Rect.fromLTWH(0, 0, 256, 256));
    });
  });

  group('mask cache', () {
    testWidgets('decodes once for every tile; debugReset releases it', (
      t,
    ) async {
      final int gen0 = HeroShimmerMask.generation.value;
      await t.pumpWidget(_host(<Widget>[_tile(), _tile()]));
      final ui.Image mask = await _awaitMask(t);
      expect(HeroShimmerMask.generation.value, gen0 + 1);
      expect(identical(HeroShimmerMask.mask?.image, mask), isTrue);

      // A third tile (and another load request) reuses the same bitmap.
      await t.pumpWidget(_host(<Widget>[_tile(), _tile(), _tile()]));
      final ui.Image? again = await _loadMask(t);
      expect(identical(again, mask), isTrue);
      expect(HeroShimmerMask.generation.value, gen0 + 1);

      HeroShimmerMask.debugReset();
      expect(HeroShimmerMask.mask, isNull);
      expect(mask.debugDisposed, isTrue);
      await t.pump(); // mounted painters repaint without the bitmap
      expect(t.takeException(), isNull);
    });

    test('concurrent requests share one in-flight decode', () async {
      final Future<ui.Image?> a = HeroShimmerMask.ensureLoaded();
      final Future<ui.Image?> b = HeroShimmerMask.ensureLoaded();
      expect(identical(a, b), isTrue);
      expect(identical(await a, await b), isTrue);
    });
  });

  group('painter', () {
    testWidgets(
      'a still frame: the base, and the bag in the highlight at 90 %',
      (t) async {
        await t.pumpWidget(_host(<Widget>[_tile()]));
        await _awaitMask(t);
        expect(_painterOf(t).clock, isNull, reason: 'a frozen tile is still');
        final ByteData px = await _shot(t);
        int channel(int x, int y, int c) => px.getUint8((y * 200 + x) * 4 + c);

        const Color base = AppColors.divider;
        const Color high = AppColors.smallBackground;
        int r8(double v) => (v * 255).round();
        // Away from the mark: the base, exactly.
        for (final (int x, int y) in const <(int, int)>[(10, 10), (190, 100)]) {
          expect(channel(x, y, 0), closeTo(r8(base.r), 1));
          expect(channel(x, y, 2), closeTo(r8(base.b), 1));
        }
        // The mark: 48 dp (the cap) centred, 76..124; between the base and
        // the tint over it, and visibly lighter somewhere.
        int maxB = 0;
        for (int y = 76; y < 124; y++) {
          for (int x = 76; x < 124; x++) {
            final int r = channel(x, y, 0), b = channel(x, y, 2);
            expect(r, inInclusiveRange(r8(base.r) - 1, r8(high.r) + 1));
            expect(b, inInclusiveRange(r8(base.b) - 1, r8(high.b) + 1));
            if (b > maxB) maxB = b;
          }
        }
        final double tintB =
            high.b * HeroImageShimmer.markAlpha +
            base.b * (1 - HeroImageShimmer.markAlpha);
        expect(maxB, closeTo(r8(tintB), 2), reason: 'the emboss reads');
      },
    );

    for (final TextDirection direction in TextDirection.values) {
      testWidgets('${direction.name}: the band enters from the start edge', (
        t,
      ) async {
        await t.pumpWidget(
          _host(<Widget>[_tile(animate: true)], direction: direction),
        );
        expect(HeroShimmerClock.isTicking, isTrue);
        await t.pump(); // the ticker's first tick: phase 0
        // 30 % into the sweep the band (stops 0.1–0.4, moved by -0.5 + 0.6
        // of the width) crosses the start half of the tile.
        await t.pump(HeroShimmerClock.period * 0.3);
        final ByteData px = await _shot(t);
        double half({required bool left}) {
          double sum = 0;
          for (int y = 0; y < 60; y++) {
            for (int x = left ? 0 : 100; x < (left ? 100 : 200); x++) {
              sum += px.getUint8((y * 200 + x) * 4 + 2);
            }
          }
          return sum;
        }

        final bool startIsLeft = direction == TextDirection.ltr;
        expect(
          half(left: startIsLeft),
          greaterThan(half(left: !startIsLeft)),
          reason: 'the highlight is in the start half',
        );
        await t.pumpWidget(const SizedBox());
        expect(HeroShimmerClock.isTicking, isFalse);
      });
    }

    test('the bag follows HeroImagePlaceholder\'s size rule', () {
      expect(HeroImageShimmerPainter.markSideFor(const Size(39, 39)), isNull);
      expect(HeroImageShimmerPainter.markSideFor(const Size(40, 40)), 16);
      expect(HeroImageShimmerPainter.markSideFor(const Size(56, 56)), 56 * 0.4);
      expect(HeroImageShimmerPainter.markSideFor(const Size(175, 90)), 36);
      expect(HeroImageShimmerPainter.markSideFor(const Size(400, 400)), 48);
    });

    testWidgets('…the very glyph size HeroImagePlaceholder draws', (t) async {
      for (final double side in <double>[30, 40, 56, 64, 120, 175, 300]) {
        await t.pumpWidget(
          Directionality(
            textDirection: TextDirection.ltr,
            child: Center(
              child: SizedBox.square(
                dimension: side,
                child: const HeroImagePlaceholder(),
              ),
            ),
          ),
        );
        final Iterable<SvgPicture> glyph = t.widgetList<SvgPicture>(
          find.byType(SvgPicture),
        );
        expect(
          glyph.isEmpty ? null : glyph.single.width,
          HeroImageShimmerPainter.markSideFor(Size.square(side)),
          reason: '$side dp',
        );
      }
    });
  });

  // The painter owns the size-keyed geometry / shader caches, so a parent
  // rebuild must hand the CustomPaint the SAME instance back; only a change
  // to a painter input (shape, live, direction) swaps it.
  group('painter + Paint caches', () {
    testWidgets('stable across rebuilds, swapped on a look change', (t) async {
      await t.pumpWidget(_host(<Widget>[_tile()]));
      final HeroImageShimmerPainter first = _painterOf(t);
      await t.pumpWidget(_host(<Widget>[_tile()]));
      expect(identical(_painterOf(t), first), isTrue);
      // A resize keeps it (its caches re-key on size internally).
      await t.pumpWidget(_host(<Widget>[_tile(size: 210)]));
      expect(identical(_painterOf(t), first), isTrue);

      await t.pumpWidget(_host(<Widget>[_tile(circular: true)]));
      final HeroImageShimmerPainter round = _painterOf(t);
      expect(identical(round, first), isFalse);
      await t.pumpWidget(_host(<Widget>[_tile(circular: true, animate: true)]));
      final HeroImageShimmerPainter live = _painterOf(t);
      expect(identical(live, round), isFalse);
      expect(live.clock, same(HeroShimmerClock.now));
      await t.pumpWidget(
        _host(<Widget>[
          _tile(circular: true, animate: true),
        ], direction: TextDirection.rtl),
      );
      expect(identical(_painterOf(t), live), isFalse);
      await t.pumpWidget(const SizedBox());
      expect(HeroShimmerClock.debugAttached, 0);
    });

    test('the mark recolour Paint is made once per tint, capped', () {
      const Color tint = Color(0xE6F1F5F9);
      final Paint paint = HeroShimmerPaints.of(tint);
      expect(identical(HeroShimmerPaints.of(tint), paint), isTrue);
      expect(
        identical(HeroShimmerPaints.of(const Color(0xE6000000)), paint),
        isFalse,
      );
      expect(paint.colorFilter, const ColorFilter.mode(tint, BlendMode.srcIn));
      // Mipmapped: the 256 px mask is drawn at 16–48 dp.
      expect(paint.filterQuality, FilterQuality.medium);
      for (int i = 0; i < 40; i++) {
        HeroShimmerPaints.of(Color(0xFF000000 + i));
      }
      expect(HeroShimmerPaints.debugCount, lessThanOrEqualTo(8));
    });

    testWidgets('many painters share one Paint per tint', (t) async {
      await t.pumpWidget(_host(<Widget>[_tile()]));
      final int one = HeroShimmerPaints.debugCount;
      await t.pumpWidget(
        _host(<Widget>[_tile(), _tile(size: 120), _tile(size: 56)]),
      );
      expect(HeroShimmerPaints.debugCount, one);
    });
  });

  // drawPaint fills the whole clip and CustomPaint never clips, so every
  // shape must be clipped to its own tile: nothing may leak past it.
  group('paint stays inside the tile', () {
    const int hostSide = 300;
    final List<(String, HeroImageShimmer, int, bool)> cases =
        <(String, HeroImageShimmer, int, bool)>[
          ('square', _tile(animate: true), 200, true),
          ('rounded', _tile(radius: 24, animate: true), 200, false),
          ('circle', _tile(circular: true, animate: true), 200, false),
          ('still rounded', _tile(size: 120, radius: 12), 120, false),
          ('small square', _tile(size: 56), 56, true),
        ];
    for (final (String name, HeroImageShimmer tile, int n, bool square)
        in cases) {
      testWidgets(name, (t) async {
        await t.pumpWidget(
          Directionality(
            textDirection: TextDirection.ltr,
            child: Center(
              child: SizedBox.square(
                dimension: hostSide.toDouble(),
                child: RepaintBoundary(
                  key: _boundary,
                  child: Align(alignment: Alignment.topLeft, child: tile),
                ),
              ),
            ),
          ),
        );
        await _awaitMask(t);
        // Live tiles: step the shared clock so the band is on the tile.
        await t.pump(HeroShimmerClock.period * 0.3);
        expect(t.takeException(), isNull);
        final ByteData px = await _shot(t);
        int alpha(int x, int y) => px.getUint8((y * hostSide + x) * 4 + 3);

        int leaked = 0;
        for (int y = 0; y < hostSide; y++) {
          for (int x = 0; x < hostSide; x++) {
            if ((x >= n || y >= n) && alpha(x, y) != 0) leaked++;
          }
        }
        expect(leaked, 0, reason: 'nothing may paint outside the tile');
        expect(alpha(n ~/ 2, n ~/ 2), 255);
        expect(alpha(0, 0), square ? 255 : 0);
        expect(alpha(n - 1, n - 1), square ? 255 : 0);
        await t.pumpWidget(const SizedBox());
      });
    }
  });

  group('one ticker, live shimmers only', () {
    testWidgets('every live tile rides one ticker; the last one stops it', (
      t,
    ) async {
      expect(HeroShimmerClock.debugAttached, 0);
      await t.pumpWidget(
        _host(<Widget>[
          _tile(animate: true),
          _tile(size: 56, animate: true),
          _tile(size: 120, animate: true, circular: true),
        ]),
      );
      expect(HeroShimmerClock.debugAttached, 3);
      expect(HeroShimmerClock.isTicking, isTrue);
      await t.pump(const Duration(milliseconds: 400));
      expect(t.takeException(), isNull);
      await t.pumpWidget(const SizedBox());
      expect(HeroShimmerClock.debugAttached, 0);
      expect(HeroShimmerClock.isTicking, isFalse);
      // The ticker's last tick (before the unmount) already asked for the
      // next frame; that frame finds nothing to tick and asks for no other.
      await t.pump();
      expect(t.binding.hasScheduledFrame, isFalse);
    });

    testWidgets('animate:false never attaches; flips stay balanced', (t) async {
      await t.pumpWidget(_host(<Widget>[_tile(), _tile()]));
      await t.pump(const Duration(seconds: 1));
      expect(HeroShimmerClock.debugAttached, 0);
      expect(t.binding.hasScheduledFrame, isFalse);

      // Flipping animate on the SAME state keeps the refcount balanced.
      await t.pumpWidget(_host(<Widget>[_tile(animate: true)]));
      expect(HeroShimmerClock.debugAttached, 1);
      await t.pumpWidget(_host(<Widget>[_tile()]));
      expect(HeroShimmerClock.debugAttached, 0);
      await t.pumpWidget(_host(<Widget>[_tile(animate: true)]));
      await t.pumpWidget(const SizedBox());
      expect(HeroShimmerClock.debugAttached, 0);
    });

    testWidgets('TickerMode off: a still frame, nothing ticks; on: it sweeps', (
      t,
    ) async {
      await t.pumpWidget(_host(<Widget>[_tile(animate: true)], tickers: false));
      expect(HeroShimmerClock.debugAttached, 0);
      expect(_painterOf(t).clock, isNull);
      await t.pump(const Duration(seconds: 1));
      expect(t.binding.hasScheduledFrame, isFalse);

      await t.pumpWidget(_host(<Widget>[_tile(animate: true)]));
      expect(HeroShimmerClock.debugAttached, 1);
      expect(_painterOf(t).clock, same(HeroShimmerClock.now));
      expect(t.binding.hasScheduledFrame, isTrue);

      await t.pumpWidget(_host(<Widget>[_tile(animate: true)], tickers: false));
      expect(HeroShimmerClock.debugAttached, 0);
      await t.pumpWidget(const SizedBox());
    });

    testWidgets('reduced motion: a still frame (base + bag), no ticker', (
      t,
    ) async {
      await t.pumpWidget(_host(<Widget>[_tile(animate: true)], reduced: true));
      await _awaitMask(t);
      expect(HeroShimmerClock.debugAttached, 0);
      expect(_painterOf(t).clock, isNull);
      final ByteData before = await _shot(t);
      await t.pump(const Duration(milliseconds: 550));
      expect(t.binding.hasScheduledFrame, isFalse);
      final ByteData after = await _shot(t);
      expect(
        after.buffer.asUint8List(),
        before.buffer.asUint8List(),
        reason: 'nothing moves',
      );
      await t.pumpWidget(const SizedBox());
    });

    testWidgets('a run is whole laps within the ambient budget, then rests; '
        'back on screen it sweeps again', (t) async {
      expect(HeroShimmerClock.laps, greaterThanOrEqualTo(1));
      expect(
        HeroShimmerClock.period * HeroShimmerClock.laps,
        lessThanOrEqualTo(AppMotion.ambientBudget),
      );
      await t.pumpWidget(_host(<Widget>[_tile(animate: true)]));
      await t.pump(); // the first tick: the run starts at 0
      final HeroImageShimmerPainter live = _painterOf(t);
      final Duration run = HeroShimmerClock.period * HeroShimmerClock.laps;
      await t.pump(run - const Duration(milliseconds: 20));
      expect(HeroShimmerClock.debugAttached, 1, reason: 'still sweeping');
      expect(identical(_painterOf(t), live), isTrue);
      await t.pump(const Duration(milliseconds: 40));
      expect(HeroShimmerClock.debugAttached, 0, reason: 'the run is spent');
      expect(_painterOf(t).clock, isNull, reason: 'its still frame');
      await t.pump(const Duration(seconds: 1));
      expect(t.binding.hasScheduledFrame, isFalse, reason: 'nothing ticks');

      // Hidden, then on screen again (a tab switch): a fresh run.
      await t.pumpWidget(_host(<Widget>[_tile(animate: true)], tickers: false));
      await t.pumpWidget(_host(<Widget>[_tile(animate: true)]));
      expect(HeroShimmerClock.debugAttached, 1);
      expect(_painterOf(t).clock, same(HeroShimmerClock.now));
      await t.pumpWidget(const SizedBox());
      expect(HeroShimmerClock.debugAttached, 0);
    });
  });
}
